  VALUES 
    (484::BIGINT, 'Excelente profesor, es súper buena gente y tiene muchísima paciencia para explicar las cosas, explica un poco rápido pero es cuestión de no distraerse, califica súper amigable, da puntos por esfuerzo, da las notas al día y ayuda en todo lo q uno ocupa, super recomendado'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2026-07-23T00:00:00+00:00'::TIMESTAMPTZ, '8932c9538a0a9dc9a5de6c5c0d41edef839bb5f64e2bc194e96d68d5b49510ae'::TEXT, ARRAY[563]::BIGINT[]),
    (484::BIGINT, 'Tiene mucha paciencia pero es verdad que sus explicaciones son confusas. De recomendación matriculen con él solo si están seguros que no se les dificulta entender la materia o ya vienen con buenas bases. Los que llegamos mal no hacemos por donde, personalmente me desmotivaba mucho ir a enredarme más'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros']::TEXT[], '2026-07-20T00:00:00+00:00'::TIMESTAMPTZ, 'be2a19638862bc26abf939e670330ad8f56b87d120e6f061490c90026973498a'::TEXT, ARRAY[563]::BIGINT[]),
    (484::BIGINT, 'No explica muy bien, asume que ud ya sabe las bases. Los quizzes son regalados y prepara bien para exámenes. Clases ordenadas, pero se despista mucho. Le cuesta explicar cuando le preguntan algo. Nota que saqué: 100'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2026-07-04T00:00:00+00:00'::TIMESTAMPTZ, '1baf28ff9e0783215a18e962a031a87e42db6cdb027db5df847782de35653c1a'::TEXT, ARRAY[563]::BIGINT[]),
