    (484::BIGINT, 'Es el mejor profe para llevar CDI casi que le regala un 25% en quices y califica los exámenes muy suave, en las clases se hacen bastantes ejercicios y ejemplos de todo tipo, full recomendado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-12-29T00:00:00+00:00'::TIMESTAMPTZ, 'a07a56466317a48181d73c87299bfe225e6f155b1c84533bea27dcaacda00ecf'::TEXT, ARRAY[605]::BIGINT[]),
