    (484::BIGINT, 'Es un curso demasiado aburrido y la catedra como siempre es una cochinada. Pero el profe es muy bueno y explica bien, es la mejor opcion para llevar este curso'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-11-29T00:00:00+00:00'::TIMESTAMPTZ, '5eba78fcefbc3f76c79664743edaac6d72cedbd5e989dc3adecd1fac61454a56'::TEXT, ARRAY[1057]::BIGINT[]),
    (484::BIGINT, 'Simplemente un amor de profesor, lo recomiendo al 100%, ojalá todos los profesores del TEC fueran cómo el'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2022-10-22T00:00:00+00:00'::TIMESTAMPTZ, 'bfc07f0d2e64076f253f9c90ea3307e3610e75ff8139e926629b02c74c5c33e2'::TEXT, ARRAY[563]::BIGINT[]),
    (484::BIGINT, 'De los mejores profesores del TEC. Explica muy bien, ayuda en consulta, brinda ejercicios claros y útiles. Excelente en todo aspecto.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-07-13T00:00:00+00:00'::TIMESTAMPTZ, 'f126dcd27cdc6dc493fd836967fe28232f061b9bbf008167eaef48bef992eba2'::TEXT, ARRAY[935]::BIGINT[]),
    (484::BIGINT, 'Super buena nota el profesor, intenta que los temas queden claros, deja de tarea ejercicios similares a los de las clases, y siempre contesta a todas las dudas dentro y fuera de las horas de clase o consulta'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes']::TEXT[], '2022-06-23T00:00:00+00:00'::TIMESTAMPTZ, '03556802fd3fa0d105d39f8cf744fe95af553655170c936a210b3a3c9397fadd'::TEXT, ARRAY[935]::BIGINT[]),
    (484::BIGINT, 'Es muy linda persona y se nota que se esfuerza mucho en sus clases. Contesta cualquier duda en clase hasta que quede todo claro, y las dudas del telegram bastante rápido. También hacía dos horas asincrónicas para que no fuese tan pesado llevar las 4 horas un sábado.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-14T00:00:00+00:00'::TIMESTAMPTZ, '8f5b15c8fc31391ce98d2cb2e61eee7e1a2d6d4831d067821248c029718352d9'::TEXT, ARRAY[935]::BIGINT[]),
    (484::BIGINT, 'Es de los mejores profes que he tenido, dos cursos con él y agradezco haberlos llevado con él. Realmente se preocupa porque se aprenda y ayuda muchísimo a aclarar dudas. Es muy pura vida.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-01T00:00:00+00:00'::TIMESTAMPTZ, '763cd8a55c0838307963b84b37a574dd7de4f6424146c5ee753db07a12919a60'::TEXT, ARRAY[935]::BIGINT[]),
    (484::BIGINT, 'Si tiene la opción de matricular con el hágalo, es de los mejores profes que tiene el TEC. Se preocupa porqué usted entienda y si tiene que aclararle una duda 300 veces lo hace. Súper recomendado.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2022-01-31T00:00:00+00:00'::TIMESTAMPTZ, 'abc770a84ccf4a575d6bdca998d01b60d256f8bfebe3fa30687bc93b8dafa6eb'::TEXT, ARRAY[1018]::BIGINT[]),
    (484::BIGINT, 'Explica muy bien y claro, excelente profesor'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-12-17T00:00:00+00:00'::TIMESTAMPTZ, '7cff02bdb7976350960ad26e4f14f24a393df49c0148f4c133ad8e79ae226b54'::TEXT, ARRAY[563]::BIGINT[]),
    (484::BIGINT, 'Es un muy pero muy buen profe , se le entiende todo , las clases son lentas xq abarca todo con claridad y deja todo bien explicando no es apurado a dar materia toda de un solo , va poco a poco ! Ayuda mucho y deja pocas tareas'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-12-07T00:00:00+00:00'::TIMESTAMPTZ, 'f59aa9bd74b24f896906e702b6cd1b99e42eb45f7e84a508fb8a4d7b6d53592f'::TEXT, ARRAY[563]::BIGINT[]),
    (484::BIGINT, 'El profe es demasiado bueno, el explica muy bien y se preocupa por el aprendizaje de los estudiantes. Las tareas que deja son muy fáciles de hacer, recomiendo mucho a este profe.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-12-06T00:00:00+00:00'::TIMESTAMPTZ, '77a235185c3536fec0b594ec76d0abbc145c727623cad78ea111de1712695aff'::TEXT, ARRAY[563]::BIGINT[]),
    (484::BIGINT, 'Explica super bien. Da buena retroalimentación, deja tareas semanalmente pero son fáciles de hacer si se asiste a clases y siempre esta dispuesto a ayudar!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-12-02T00:00:00+00:00'::TIMESTAMPTZ, '37b83d6d5c164bbe4832d5ac33b6e9762d7d3560871222368da5852c4cc88f5f'::TEXT, ARRAY[563]::BIGINT[]),
    (484::BIGINT, 'Demasiado buen profe. Las clases son super claras y muy buenas, da ejemplos que permiten el máximo entendimiento del tema, ayuda mucho, brinda apoyo y las evaluaciones no son rudas. Se puede pasar el curso solo viendo las clases del profe.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-11-01T00:00:00+00:00'::TIMESTAMPTZ, 'e7ed208997ee4aaf26f22f957cc7dec2fc2538fd212652bc1205720a2222a99b'::TEXT, ARRAY[634]::BIGINT[]),
    (484::BIGINT, 'Un profesor que realmente se preocupa por que el estudiante entienda'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-20T00:00:00+00:00'::TIMESTAMPTZ, '93e4ca1edf6c0f9f828dc594a18c3989aeef3d4b32f4c202f83befd31b9cc1b3'::TEXT, ARRAY[1018]::BIGINT[]),
    (484::BIGINT, 'Realmente se preocupa por el estudiante. Responde super rápido por telegram y es muy claro explicando. Las tareas y quices que deja son muy sencillos de hacer si puso atención en clases. Si uno pide tiempo extra se lo da. 100% recomendado.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-16T00:00:00+00:00'::TIMESTAMPTZ, '7f2cf505465b72f57092e4794964f14a80f2009f29d5d3beb4098162a9139003'::TEXT, ARRAY[935]::BIGINT[]),
    (484::BIGINT, 'Es un profe excelente, siempre intenta ayudar y hacer que todo quede claro. Recuerda siempre las asignaciones, y despeja cualquier duda en cualquier momento. Súper recomendado.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-14T00:00:00+00:00'::TIMESTAMPTZ, '55d3cb961bd2e4e36c05328c3476ced9f89789f65145f3fc952dd2da10a0ec55'::TEXT, ARRAY[1641]::BIGINT[]),
    (484::BIGINT, 'Este profe es súper bueno, ama lo que hace, brinda apoyo, permite que se hagan preguntas en cualquier momento durante la explicación, hace muchas preguntas, nos comprende, este mae es un pro sinceramente, se preocupa por todos el mae 1000000/10'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Inspirador', 'Clases excelentes']::TEXT[], '2021-07-10T00:00:00+00:00'::TIMESTAMPTZ, 'c7ae9047129b0e1227ab7dba3867fc9b8f2de455dde921e1cc4b9c9d6f3eca4c'::TEXT, ARRAY[634]::BIGINT[]),
    (484::BIGINT, 'El mejor profe de mate. Responde por Telegram a cualquier hora, demasiado amable y siempre está dispuesto a ayudarlo a uno así falten 5 minutos para entregar la tarea o para que empiece el examen. Recomendadísimo, explica la materia de una manera muy fácil de entender.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2021-07-03T00:00:00+00:00'::TIMESTAMPTZ, 'be689726f184c98d2c851ce0872a2ce01e36a4bc0c8615c6571f9245d6602e8a'::TEXT, ARRAY[935]::BIGINT[]),
    (484::BIGINT, 'Se nota el interés del profe, explica super bien y como persona un 10/10. Deja como unas 6 tareas que son decentes y ayudan a refrescar temas'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-25T00:00:00+00:00'::TIMESTAMPTZ, '30334046b4fa0ef681aac7f84cd5ab2dc8c7db642d0de375472279882e27a74c'::TEXT, ARRAY[634]::BIGINT[]),
    (484::BIGINT, 'Top 3 de mejores profes junto con Murillo y Masis. Da notas muy rápido, ayuda mil y se interesa por los estudiantes. Es mega ordenado y contesta por telegram super rápido. Metan sin pensar con él. MEGA EXCELENTE!!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-23T00:00:00+00:00'::TIMESTAMPTZ, '990e3c01d5bfe18f843522f2675837e1de3c8f9db36f8c67bbac554311eab29a'::TEXT, ARRAY[935]::BIGINT[]),
    (484::BIGINT, 'Este profe es muy bueno, explica genial, se nota la vocación que posee para la enseñanza y siempre esta pendiente de todo. Además que sus evaluaciones tienen un nivel medio y no muy largas que ayudan para el examen. Por suerte CAL que es super fácil pero este profe ayuda a que lo sea aun mas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Deja trabajos largos', 'Clases excelentes']::TEXT[], '2021-06-21T00:00:00+00:00'::TIMESTAMPTZ, '39e57a4998babf1778cf9d401e9843cc2b0347566f3d9a5477a8114df44406af'::TEXT, ARRAY[634]::BIGINT[]),
    (484::BIGINT, 'Muy buen profe y explica súper bien. Aclara todas las dudas que tenga.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-14T00:00:00+00:00'::TIMESTAMPTZ, '4fdd1d9c7666b0df5274aa42601602604e39c9d52d14d664e3b8158100061500'::TEXT, ARRAY[634]::BIGINT[]),
    (484::BIGINT, 'Es increíble. Es atento, es buen profe y siempre responde dudas incluso fuera de horario laboral. Lo recomiendo 100% porque se aprende y el curso lo facilita'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-12T00:00:00+00:00'::TIMESTAMPTZ, 'cc536d6e1af9e38771f36137849cbfbcaef33b794eb2cb53869ecfc36e668bba'::TEXT, ARRAY[1641]::BIGINT[]),
    (484::BIGINT, 'Explica súper bien y de forma interactiva. Muy humilde, una calidad de persona en general. Facilita enormemente el curso. Siempre está dispuesto a ayudar.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Brinda apoyo']::TEXT[], '2021-02-05T00:00:00+00:00'::TIMESTAMPTZ, 'e25ccd9403558eed1a162dafdb2a469f281a4d579b1eb8b00adcefdfd2fe8810'::TEXT, ARRAY[605]::BIGINT[]),
    (484::BIGINT, 'Gran profesor y gran persona. Sencillez, dedicación, disponibilidad, compromiso, lo tiene todo. Se preocupa porque el estudiante aprenda, las clases y horas de consulta son excelentes, siempre está dispuesto a ayudar. Sin duda llevaría otros cursos con él.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-02-04T00:00:00+00:00'::TIMESTAMPTZ, 'd06667cbf3b4d0546c3aa16880d8fb54e28b032674847565c62a8e079d105e0d'::TEXT, ARRAY[605]::BIGINT[]),
    (484::BIGINT, 'El mejor profesor que conozco. Gracias a él pasé Cálculo a la segunda (a la primera metí con Azofeifa y terrible) y Álgebra a la primera. Debería dar clases en Cartago porque cuando se acabe la virtualidad ya no voy a poder ver sus clases porque da en Alajuela:('::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-01-27T00:00:00+00:00'::TIMESTAMPTZ, '5513a141d0d3ce679aa0eb8b8ca01b05a90fce1fe020ff19aff2ed90b91a149f'::TEXT, ARRAY[1641]::BIGINT[]),
    (484::BIGINT, 'Si están repitiendo el curso, llévenlo con él, se ve que le encanta enseñar, la verdad de los mejores profes que pude tener respecto a este h* curso, lastima que el mae solo de clases en Alajuela, se necesita un profe como él que de discreta en Cartago.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-01-27T00:00:00+00:00'::TIMESTAMPTZ, '686dcb46f3e20275879f1a7313f61bad6ee86d741ed03d03ef9e83d7c88eebf3'::TEXT, ARRAY[1018]::BIGINT[]),
    (484::BIGINT, 'He repetido mate discreta varias veces, llega un punto en que la materia se complica bastante pero el profesor hace todo el esfuerzo para que los estudiantes aprendan y salgan adelante. Si ven su nombre, matriculen automáticamente el curso'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-11-08T00:00:00+00:00'::TIMESTAMPTZ, '142b0e80d1a035c1ae998ae1ab09fcb6cb02661a0453222ee4fe1a304c0ec6c4'::TEXT, ARRAY[1018]::BIGINT[]),
    (484::BIGINT, 'Excelente profesor. Explica claro y si usted no entendió él le explica de nuevo sin burlarse y con muy buena voluntad. Crea un ambiente muy ameno en el que uno se siente con confianza de preguntarle si no entendió.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-31T00:00:00+00:00'::TIMESTAMPTZ, '75a10c38b67ecf371f2838cde0332b3616d944717e12b9596796a96028d56bbc'::TEXT, ARRAY[605]::BIGINT[]),
    (484::BIGINT, 'Simplemente excelente profesor, ayuda demasiado cuando uno no entiende, evacua todas las dudas y se le entiende mucho la explicación El mejor profesor que he tenido de la cátedra de mate hasta el momento.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Inspirador', 'Brinda apoyo']::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, 'a94ab67d1f60ddf703d7ea45ad53419ed0761f82a76ec740835b6a3de867e40c'::TEXT, ARRAY[605]::BIGINT[]),
    (484::BIGINT, 'Excelente profe sin lugar a dudas. Sin objeciones'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-10T00:00:00+00:00'::TIMESTAMPTZ, '27269d3e7f351177b7a13a1cf23914747ebc43b78d864a68793c0835fa384039'::TEXT, ARRAY[605]::BIGINT[]),
    (484::BIGINT, 'Siempre está preguntando si entendemos la materia, y siempre está dispuesto a aclarar dudas. Muy pura vida y deja una cantidad decente de tareas para ayudarse a estudiar. En virtual es muy bueno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-09T00:00:00+00:00'::TIMESTAMPTZ, '21a9ba81a43e85f1054ad488482e16c432120bffeabc2eeb4960c01f433df2ec'::TEXT, ARRAY[605]::BIGINT[]),
    (484::BIGINT, 'Es un excelente profe, si buscan un profe de calculo amable y que les ayude el es el profe. Muy a gusto como explicaba y nos brindaba ayuda'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-07-30T00:00:00+00:00'::TIMESTAMPTZ, '77f7eaae4addc7db28df0cd6ee94dc3303e4b26584719d082e395830e891443c'::TEXT, ARRAY[605]::BIGINT[]),
    (484::BIGINT, 'Genial! toda la materia súper clara, en taller es excelente. El profe tiene mucha paciencia y si no entienden algo explica las veces que sea necesario y siempre está dispuesto a ayudar! 20/10'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2020-07-28T00:00:00+00:00'::TIMESTAMPTZ, 'a94dd6c2aa42ae6d944449909e5e5659f6c1787c663ab5d6a60bccff5afadd16'::TEXT, ARRAY[605]::BIGINT[])
